import React, { useState } from 'react';
import API from '../api';

const ExamData = () => {
  const [franchiseId, setFranchiseId] = useState('');
  const [formData, setFormData] = useState({
    examName: '',
    date: '',
    studentsAttended: '',
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await API.put(`/franchises/${franchiseId}/exam-data`, formData);
      alert('Exam data updated successfully!');
    } catch (error) {
      alert('Error updating exam data: ' + error.response.data.message);
    }
  };

  return (
    <div>
      <h1>Manage Exam Data</h1>
      <input
        placeholder="Franchise ID"
        value={franchiseId}
        onChange={(e) => setFranchiseId(e.target.value)}
        required
      />
      <form onSubmit={handleSubmit}>
        <input name="examName" placeholder="Exam Name" onChange={handleChange} required />
        <input name="date" type="date" onChange={handleChange} required />
        <input name="studentsAttended" type="number" onChange={handleChange} required />
        <button type="submit">Update Exam Data</button>
      </form>
    </div>
  );
};

export default ExamData;
